/* buyer.mprq.selectLtalPriceConfirmAppInfo */ SELECT K.*, MAX( CASE WHEN K.RANK = 1 THEN DESCRIPTION ELSE '' END) OVER () || CASE WHEN CNT != 1 THEN ' 외 ' || TO_CHAR(K.CNT - 1) || '건' ELSE '' END AS SUBJECT FROM ( SELECT (SELECT MAX(TEXT4) FROM ICOMCOD2 WHERE TYPE = 'C002' AND TEXT2 = RQ.BUYER AND COMPANY_CODE = C.BYCA_COMORG_CODE) AS PLANT, RQ.QUOTATION_NO, RQ.QUOTATION_SEQ, CASE WHEN RQ.BUYER_ITEM_NO LIKE 'NO_CODE%' THEN ' ' ELSE RQ.BUYER_ITEM_NO END AS BUYER_ITEM_NO, NVL(RQ.DESCRIPTION,' ') AS DESCRIPTION, NVL(RQ.SPECIFICATION,' ') AS SPECIFICATION, NVL(RQ.UNIT_MEASURE,' ') AS UNIT_MEASURE, NVL(RQ.ITEM_QTY,0) AS ITEM_QTY, NVL(RQ.BTOA_DATE,' ') AS BTOA_DATE, NVL(RQ.BTOA_END_DATE,' ') AS BTOA_END_DATE, NVL(QT.LEAD_TIME,' ') AS DELIVERY_LT, NVL(QT.MAKER_NAME,' ') AS MAKER_NAME, NVL(QT.ORIGIN_NAME,' ') AS ORGIN_NAME, NVL(RQ.BUYER_TARGET_PRICE,0) AS TARGET_PRICE, NVL(RQ.ATOB_UNIT_PRICE,0) AS ATOB_UNIT_PRICE, NVL(RQ.BTOA_USER_NAME,' ') AS REQ_USER_NAME, NVL(RQ.BTOA_USER_DEPT,' ') AS REQ_USER_DEPT_NAME, NVL(RQ.ATOB_REMARK,' ') AS ATOB_REMARK, ROW_NUMBER() OVER (ORDER BY RQ.PLANT, RQ.QUOTATION_NO, RQ.QUOTATION_SEQ) AS RANK, COUNT(*) OVER () AS CNT FROM KEPRQDT RQ , KEPQTDT QT , ICOMCMPY C WHERE RQ.BUYER IN (SELECT BUYER FROM IF_ADMIN WHERE BUYER_ID = 'LTAL2') AND RQ.GW_NO = #{GW_NO} AND RQ.STATUS != 'D'
AND QT.BUYER = RQ.BUYER AND QT.QUOTATION_NO = RQ.QUOTATION_NO AND QT.QUOTATION_SEQ = RQ.QUOTATION_SEQ AND QT.REVISION = RQ.REVISION AND QT.BID_SUCCESS_FLAG = 'Y' AND QT.STATUS = 'C'
AND C.COM_CODE = RQ.BUYER ) K ORDER BY RANK


